/* real lon/lat -> map viewBox units (same projection the province paths use) */
function projectLonLat(lon, lat){
  const x = lon * Math.PI / 180;
  const y = Math.asinh(Math.tan(lat * Math.PI / 180));
  return {x: GEO.pad + (x - GEO.proj.xmin) * GEO.proj.k, y: GEO.pad + (GEO.proj.ymax - y) * GEO.proj.k};
}
